def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Label 4-connected components of zeros and note which touch the border.
    zero_id = [[-1] * w for _ in range(h)]
    enclosed = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or zero_id[r][c] != -1:
                continue
            k = len(enclosed)
            stack = [(r, c)]
            zero_id[r][c] = k
            touches_edge = False
            while stack:
                y, x = stack.pop()
                if y == 0 or y == h - 1 or x == 0 or x == w - 1:
                    touches_edge = True
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 0
                            and zero_id[ny][nx] == -1):
                        zero_id[ny][nx] = k
                        stack.append((ny, nx))
            enclosed.append(not touches_edge)

    # Label 4-connected components of ones.
    one_id = [[-1] * w for _ in range(h)]
    one_components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or one_id[r][c] != -1:
                continue
            k = len(one_components)
            stack = [(r, c)]
            one_id[r][c] = k
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 1
                            and one_id[ny][nx] == -1):
                        one_id[ny][nx] = k
                        stack.append((ny, nx))
            one_components.append(cells)

    # Components of ones bordering an enclosed region get an outside halo (2);
    # enclosed zeros next to their outline are colored 3.
    selected = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or not enclosed[zero_id[r][c]]:
                continue
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    ny, nx = r + dy, c + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 1:
                        selected.add(one_id[ny][nx])
                        out[r][c] = 3

    for k in selected:
        for r, c in one_components[k]:
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    ny, nx = r + dy, c + dx
                    if (0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 0
                            and out[ny][nx] != 3):
                        out[ny][nx] = 2

    return out
